window.AUTH=window.AUTH||{};window.AUTH["22-340"]={"d":"22-340","id":"2023/22-340","n":"Pulsifer v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Mark E. Pulsifer","date":"2023-05-19","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/267269/20230519142156758_Pulsifer%20v.%20United%20States%20Merits%20Brief%20FILE.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondent United States","date":"2023-07-24","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/272805/20230724211315733_22-340bsUnitedStates.pdf","side":"res","n":93},{"k":"reply","label":"Reply of petitioner Mark E. Pulsifer","date":"2023-08-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-340/276008/20230823133339428_Pulsifer%20v.%20United%20States%20Reply%20Brief%20for%20Petitioner%20FILE.pdf","side":"pet","n":47}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us1r07_19m1.pdf","tr":true,"items":[{"t":"case","label":"62 Cases of Jam v. United States","cite":"340 U.S. 593","y":1951,"id":"scdb/1950-050","sc":1,"by":{"0":"28","2":"11"}},{"t":"case","label":"Babb v. Wilkie","cite":"140 S. Ct. 1168","y":2020,"id":"2019/18-882","sc":1,"by":{"0":"17, 20"},"q":[{"src":"brief","b":0,"text":"it is not necessary to go any further.","cite":"140 S. Ct. at 1172, 1177"}]},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"by":{"0":"47, 48","1":"46"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"Part of a fair reading of statutory text is recognizing that ‘Congress legislates against the backdrop’ of certain unexpressed presumptions.","cite":"572 U.S. 844, 857"}]},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"0":"12, 13, 20, 21, 29","1":"30, 42","2":"14"},"q":[{"src":"brief","b":0,"text":"that a given term is used to mean the same thing throughout a statute, a presumption surely at its most vigorous when a term is repeated within a given sentence.","cite":"513 U.S. at 118"},{"src":"brief","b":1,"text":"a given term is used to mean the same thing throughout a statute.","cite":"513 U.S. at 118"}]},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"by":{"0":"43, 48, 49","2":"22"},"q":[{"src":"brief","b":0,"text":"The role of this Court is to apply the statute as it is written—even if [it] think[s] some other approach might ‘accord with good policy.’","cite":"571 U.S. 204, 218"},{"src":"brief","b":0,"text":"cannot give the text a meaning that is different from its ordinary, accepted meaning, and that disfavors the defendant.","cite":"571 U.S. at 216"},{"src":"brief","b":2,"text":"a criminal statute … a meaning that is different from its ordinary, accepted meaning, and that disfavors the defendant.","cite":"571 U.S. 204, 216"}]},{"t":"case","label":"Callanan v. United States","cite":"364 U.S. 587","y":1961,"id":"1960/47","sc":1,"by":{"0":"48"}},{"t":"case","label":"Concepcion v. United States","cite":"142 S. Ct. 2389","y":2022,"id":"2021/20-1650","sc":1,"by":{"0":"23, 24, 25","2":"3, 20"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"0":"17, 34"},"q":[{"src":"brief","b":0,"text":"courts must presume that a legislature says in a statute what it means and means in a statute what it says there.","cite":"503 U.S. 249, 253-54"}]},{"t":"case","label":"Crooks v. Harrelson","cite":"282 U.S. 55","y":1930,"id":"scdb/1930-011","sc":1,"by":{"0":"43","1":"36"},"q":[{"src":"brief","b":0,"text":"to override the literal terms of a statute only under rare and exceptional circumstances.","cite":"282 U.S. 55, 60"},{"src":"brief","b":0,"text":"Laws enacted with good intention, when put to the test, frequently, and to the surprise of the lawmaker himself, turn out to be mischievous, absurd or otherwise objectionable. But in such case the remedy lies with the lawmaking authority, and not with the courts.","cite":"282 U.S. at 60"},{"src":"brief","b":1,"text":"override the literal terms of a statute.","cite":"282 U.S. 55, 60"}]},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Retirement Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"by":{"0":"33"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","id":"2020/18-956","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"‘But that understanding has little to do with syntax and everything to do with our common understanding that’ drinking and smoking can be harmful individually.","cite":"141 S. Ct. 1163, 1174"}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"0":"27, 33","2":"11"},"q":[{"src":"brief","b":0,"text":"job [is] to apply faithfully the law Congress has written,","cite":"582 U.S. 79, 89"},{"src":"brief","b":2,"text":"apply faithfully the law Congress has written.","cite":"582 U.S. 79, 89"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"that whatever might appear to further the statute's primary objective must be the law.","cite":"582 U. S. 79, 89"}]},{"t":"case","label":"HollyFrontier Cheyenne Refining, LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"by":{"0":"27"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"0":"33"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"by":{"0":"22"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"by":{"0":"34, 35","2":"3, 17"}},{"t":"case","label":"Logan v. United States","cite":"552 U.S. 23","y":2007,"id":"2007/06-6911","sc":1,"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"could not conceivably have ... intended","cite":"552 U.S. 23, 36"}]},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"by":{"0":"34, 35","1":"33"}},{"t":"case","label":"Lynch v. Alworth-Stephens Co.","cite":"267 U.S. 364","y":1925,"id":"scdb/1924-237","sc":1,"by":{"0":"17, 20, 26"},"q":[{"src":"brief","b":0,"text":"the plain, obvious and rational meaning of a statute is always to be preferred to any curious, narrow, hidden sense that nothing but the exigency of a hard case and the ingenuity and study of an acute and powerful intellect would discover.","cite":"267 U.S. 364, 370"},{"src":"brief","b":0,"text":"any curious, narrow, hidden sense that nothing but the exigency of a hard case and the ingenuity and study of an acute and powerful intellect would discover.","cite":"267 U.S. at 370"}]},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"0":"48"},"q":[{"src":"brief","b":0,"text":"grievous ambiguity or uncertainty in the statute such that the Court must simply guess as to what Congress intended.","cite":"570 U.S. 48, 76"}]},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"34, 35","2":"17"},"q":[{"src":"brief","b":0,"text":"The canon against surplusage is not an absolute rule,","cite":"568 U.S. 371, 385"},{"src":"brief","b":0,"text":"has considerably less force in this case,","cite":"568 U.S. at 385"}]},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"by":{"0":"48","1":"48"},"q":[{"src":"brief","b":0,"text":"reasonable doubt persists about a statute’s intended scope,","cite":"498 U.S. 103, 108"}]},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"by":{"0":"45","2":"3, 6, 21"},"q":[{"src":"brief","b":0,"text":"no amount of policytalk can overcome [Congress’] plain statutory command.","cite":"141 S. Ct. 1474, 1486"},{"src":"brief","b":2,"text":"no amount of policy-talk can overcome a plain statutory command.","cite":"141 S. Ct. 1474, 1486"},{"src":"brief","b":2,"text":"give the law’s terms their ordinary meaning,","cite":"141 S. Ct. at 1486"}]},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"so clear as to be obvious to most anyone.","cite":"491 U.S. 440, 471"}]},{"t":"case","label":"Rimini Street, Inc. v. Oracle USA, Inc.","cite":"139 S. Ct. 873","y":2019,"id":"2018/17-1625","sc":1,"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"the better overall reading of [a] statute,","cite":"139 S. Ct. 873, 881"}]},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"[d]eciding what competing values will or will not be sacrificed to the achievement of a particular objective is the very essence of legislative choice—and it frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be the law.","cite":"480 U.S. 522, 525-26"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"by":{"0":"17"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"47"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"by":{"0":"20, 33, 42","1":"42","2":"16"},"q":[{"src":"brief","b":0,"text":"to elevate vague invocations of statutory purpose over the words Congress chose.","cite":"142 S. Ct. at 1792"},{"src":"brief","b":2,"text":"elevate vague invocations of statutory purpose over the words Congress chose.","cite":"142 S. Ct. 1783, 1792-93"}]},{"t":"case","label":"United States v. Atlantic Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"by":{"0":"34"}},{"t":"case","label":"United States v. Garcon","cite":"54 F.4th 1274","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/54/1274/","by":{"0":"40, 41, 42, 44, 45, 46, 49","1":"44","2":"3"},"q":[{"src":"brief","b":0,"text":"it appears to have been crafted by the government specifically for this statute to achieve its preferred outcome.","cite":"54 F.4th 1274, 1280"},{"src":"brief","b":0,"text":"inject[ing] the words ‘does not have’ into the statute where they do not appear.","cite":"54 F.4th at 1280"},{"src":"brief","b":2,"text":"make § 3553(f)(1) say what it objectively, demonstrably, verifiably does not say.","cite":"54 F.4th 1274, 1290"},{"src":"argument","who":"Mr. Dvoretzky","text":"It -- there -- you can find individual cases where that would be true, but as Chief Judge Pryor explained in the Garcon case, Congress legislates at a macro level, not at a micro level."},{"src":"argument","who":"Justice Jackson","text":"-- what Judge Pryor said in the Garcon case? I mean, I -- I took you to be sort of embracing his philosophy as to how the guidelines work relative to the mandatory minimums and that it is not irrational at all for Congress to be making the amendment that they were making in this case, which was intended to broaden the -- the availability of the safety valve."},{"src":"argument","who":"Mr. Dvoretzky","text":"I would -- even in that circumstance, as Judge Newsom, for example, said in Garcon, you would still have to adhere to the ordinary meaning of \"and\" in -- in this situation, and the surplusage would not matter."}]},{"t":"case","label":"United States v. Haynes","cite":"55 F.4th 1075","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/1075/","by":{"0":"11, 37, 40, 44","1":"21, 22, 36, 43"},"q":[{"src":"brief","b":1,"text":"to deny a defendant the extraordinary relief afforded by the safety valve.","cite":"55 F.4th 1075, 1079"},{"src":"brief","b":1,"text":"an ordinary reader would expect that § 3553(f )(1) itself would serve as a gatekeeper—and not an arbitrary one.","cite":"55 F.4th at 1080"}]},{"t":"case","label":"United States v. Jones","cite":"60 F.4th 230","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/230/","by":{"0":"35, 37, 40, 43, 44","2":"14, 15"},"q":[{"src":"brief","b":0,"text":"to convey that the satisfaction of a single listed condition is disqualifying,","cite":"60 F.4th 230, 235"},{"src":"brief","b":0,"text":"The meaning of ‘and’ does not change simply because it is preceded by a negative marker.","cite":"60 F.4th at 233"},{"src":"brief","b":2,"text":"that the satisfaction of a single listed condition is disqualifying,","cite":"60 F.4th 230, 235"}]},{"t":"case","label":"United States v. Lopez","cite":"998 F.3d 431","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/998/431/","by":{"0":"25, 29, 35, 44, 49","1":"35, 45","2":"11"},"q":[{"src":"brief","b":0,"text":"this far-fetched and quixotic em-dash theory,","cite":"998 F.3d at 441"},{"src":"brief","b":1,"text":"Congress meant what it said. Two points is two points. Two points is not three points.","cite":"998 F.3d 431, 445"},{"src":"argument","who":"Mr. Dvoretzky","text":"Second, on a factual level, in response to those numbers, those numbers, the 2.8 percent or whatever it is, that's calculating things under the Ninth Circuit's Lopez interpretation."},{"src":"argument","who":"Mr. Dvoretzky","text":"And if the government -- the other thing I would add is, if the government's view were correct that any of A, B, or C were independently disqualifying, you could have people disqualified as in the Lopez case, for example, for a 14-year-old offense for spray-painting a building."},{"src":"argument","who":"Justice Gorsuch","text":"They said -- they -- they said that \"The parties discuss whether 'and' should be read conjunctively or disjunctively, but we do not believe that is the important question.\" The government also argued the \"and\" versus \"or\" theory in Lopez in -- in front of the Ninth Circuit."}]},{"t":"case","label":"United States v. Pace","cite":"48 F.4th 741","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/741/","by":{"0":"39, 41, 44, 46, 47","1":"26","2":"12"},"q":[{"src":"brief","b":0,"text":"has the virtue of consistency with Congress’s purpose.","cite":"48 F.4th at 762"},{"src":"brief","b":0,"text":"it is not hard to imagine situations in which the conjunctive reading does not render [§ 3553(f)(1)(A)] superfluous.","cite":"48 F.4th at 763"},{"src":"brief","b":2,"text":"the most important textual basis for [the] ‘distributive’ reading,","cite":"48 F.4th 741, 754"}]},{"t":"case","label":"United States v. Palomares","cite":"52 F.4th 640","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/52/640/","by":{"0":"35, 37, 44, 46, 49","2":"12, 13, 17"},"q":[{"src":"brief","b":0,"text":"hold that it is reasonable to read ‘or’ for ‘and.’","cite":"52 F.4th 640, 652"},{"src":"brief","b":0,"text":"Style guides, dictionaries, books on grammar, and the like are silent on whether putting an em-dash after the negative phrase changes its meaning.","cite":"52 F.4th at 654"},{"src":"brief","b":2,"text":"an inferential rule of Boolean algebra,","cite":"52 F.4th at 649"},{"src":"brief","b":2,"text":"would effectively eliminate all mandatory minimums for drug crimes.","cite":"52 F.4th at 654"}]},{"t":"case","label":"United States v. Palomar-Santiago","cite":"141 S. Ct. 1615","y":2021,"id":"2020/20-437","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Wiltberger","cite":"5 Wheat. 76","y":1820,"url":"https://www.courtlistener.com/c/Wheat./5/76/","by":{"0":"48"},"q":[{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"is perhaps not much less old than construction itself.","cite":"5 Wheat. 76, 95"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"defne a crime, and ordain its punishment.","cite":"5 Wheat., at 95"},{"src":"argument","who":"Justice Gorsuch","text":"And then, three, lenity, which is the word that we dare not utter but which Chief Justice Marshall back in Wiltberger said applies before you get to things like legislative history and what Congress might have wanted and policy arguments."}]},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"47, 48, 49"},"q":[{"src":"brief","b":0,"text":"the tools of statutory interpretation before resorting to the rule of lenity.","cite":"142 S. Ct. at 1075"}]},{"t":"usc","label":"18 U.S.C. § 845","url":"https://www.law.cornell.edu/uscode/text/18/845","subs":["(a)"],"stext":{"head":"§845. Exceptions; relief from disabilities","paras":[[0,"(a) Except in the case of subsection (l), (m), (n), or (o) of section 842 and subsections (d), (e), (f), (g), (h), and (i) of section 844 of this title, this chapter shall not apply to:"],[1,"(1) aspects of the transportation of explosive materials via railroad, water, highway, or air that pertain to safety, including security, and are regulated by the Department of Transportation or the Department of Homeland Security;"],[1,"(2) the use of explosive materials in medicines and medicinal agents in the forms prescribed by the official United States Pharmacopeia, or the National Formulary;"],[1,"(3) the transportation, shipment, receipt, or importation of explosive materials for delivery to any agency of the United States or to any State or political subdivision thereof;"],[1,"(4) small arms ammunition and components thereof;"],[1,"(5) commercially manufactured black powder in quantities not to exceed fifty pounds, percussion caps, safety and pyrotechnic fuses, quills, quick and slow matches, and friction primers, intended to be used solely for sporting, recreational, or cultural purposes in antique firearms as defined in section 921(a)(16) of title 18 of the United States Code, or in antique devices as exempted from the term \"destructive device\" in section 921(a)(4) of title 18 of the United States Code;"],[1,"(6) the manufacture under the regulation of the military department of the United States of explosive materials for, or their distribution to or storage or possession by the military or naval services or other agencies of the United States; or to arsenals, navy yards, depots, or other establishments owned by, or operated by or on behalf of, the United States 1 and"],[1,"(7) the transportation, shipment, receipt, or importation of display fireworks materials for delivery to a federally recognized Indian tribe or tribal agency."],[0,"(b)(1) A person who is prohibited from shipping, transporting, receiving, or possessing any explosive under section 842(i) may apply to the Attorney General for relief from such prohibition."],[0,"(2) The Attorney General may grant the relief requested under paragraph (1) if the Attorney General determines that the circumstances regarding the applicability of section 842(i), and the applicant's record and reputation, are such that the applicant will not be likely to act in a manner dangerous to public safety and that the granting of such relief is not contrary to the public interest."],[0,"(3) A licensee or permittee who applies for relief, under this subsection, from the disabilities incurred under this chapter as a result of an indictment for or conviction of a crime punishable by imprisonment for a term exceeding 1 year shall not be barred by such disability from further operations under the license or permit pending final action on an application for relief filed pursuant to this section."],[0,"(c) It is an affirmative defense against any proceeding involving subsections (l) through (o) of section 842 if the proponent proves by a preponderance of the evidence that the plastic explosive—"],[1,"(1) consisted of a small amount of plastic explosive intended for and utilized solely in lawful—"],[2,"(A) research, development, or testing of new or modified explosive materials;"],[2,"(B) training in explosives detection or development or testing of explosives detection equipment; or"],[2,"(C) forensic science purposes; or"],[1,"(2) was plastic explosive that, within 3 years after the date of enactment of the Antiterrorism and Effective Death Penalty Act of 1996, will be or is incorporated in a military device within the territory of the United States and remains an integral part of such military device, or is intended to be, or is incorporated in, and remains an integral part of a military device that is intended to become, or has become, the property of any agency of the United States performing military or police functions (including any military reserve component) or the National Guard of any State, wherever such device is located."],[1,"(3) For purposes of this subsection, the term \"military device\" includes, but is not restricted to, shells, bombs, projectiles, mines, missiles, rockets, shaped charges, grenades, perforators, and similar devices lawfully manufactured exclusively for military or police purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/845?type=usc&year=mostrecent&link-type=html"},"by":{"0":"47","1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(f)","(f)(1)","(f)(1)(2017)","(f)(1)(A)","(f)(1)(B)","(f)(1)(C)","(f)(2)","(f)(2)(C)","(f)(3)","(f)(4)","(f)(5)","(a)(4)","(g)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"13, 23, 25, 29, 30, 31, 40, 41, 45, 47, 35, 36, 40, 42, 43, 44, 45, 46, 47, 49, 50, 8, 42, 37, 38, 39, 40, 41, 42, 44, 45, 46, 50, 33, 35, 36, 38, 41, 42, 44, 45, 46, 50, 6, 8, 9, 21, 24, 25, 29, 30, 31, 45, 25, 21, 24, 25, 29, 30, 31, 45, 21, 24, 25, 29, 30, 31, 45, 21, 24, 25, 29, 30, 31, 45","1":"32, 41, 41, 41, 41, 41, 41, 41, 41, 41","2":"13, 14, 15, 23, 17, 18, 19, 20, 21, 22, 23, 24, 17, 18, 19, 20, 24, 17, 18, 19, 20, 21, 24, 17, 18, 19, 20, 24, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20, 1, 12, 13, 14, 15, 20"},"q":[{"src":"brief","b":0,"text":"not have more than 1 criminal history point, as determined under the sentencing guidelines.","cite":"18 U.S.C. § 3553(f)(1)"},{"src":"brief","b":0,"text":"does not have—(A) more than 4 criminal history points, excluding any criminal history points resulting from a 1-point offense, as determined under the sentencing guidelines; (B) a prior 3-point offense, as determined under the sentencing guidelines; and (C) a prior 2-point violent offense, as determined under the sentencing guidelines.","cite":"18 U.S.C. § 3553(f)(1)"},{"src":"brief","b":1,"text":"more than 4 criminal history points, excluding any criminal history points resulting from a 1-point offense.","cite":"18 U.S.C. 3553"},{"src":"brief","b":1,"text":"3-point offense, as determined under the sentencing guidelines.","cite":"18 U.S.C. 3553"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"(5) not later than the time of the sentencing hearing, the defendant has truthfully provided to the Government all information and evidence the defendant has Gorsuch, J., dissenting concerning the offense or offenses that were part of the same . . . common scheme or plan . . . .","cite":"18 U. S. C. § 3553(f)"}]},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)","(b)(1)(A)(viii)","(b)(1)(A)(v)","(b)(1)(B)","(b)(1)(B)(viii)","(b)(1)(B)(v)","(b)(1)(C)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8","1":"4, 22, 46, 3, 7, 3, 7, 22, 4, 4, 4, 7, 4, 4, 4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"usc","label":"41 U.S.C. § 6702","url":"https://www.law.cornell.edu/uscode/text/41/6702","subs":["(b)"],"by":{"0":"47","1":"41"}},{"t":"law","label":"Pub. L. No. 115-391","url":"https://www.govinfo.gov/link/plaw/115/public/391","by":{"0":"8","1":"5"}},{"t":"case","label":"Abbott v. United States","cite":"562 U.S. 8","y":2010,"id":"2010/09-479","sc":1,"by":{"1":"48"},"q":[{"src":"argument","who":"Mr. Liu","text":"The Court rejected that because it called that result \"strange and bizarre.\" In Abbott versus the United States, which -- which we discuss in our brief, this Court addressed the applicability of 924(c)'s mandatory consecutive sentence regime."}]},{"t":"case","label":"Biden v. Nebraska","cite":"143 S. Ct. 2355","y":2023,"id":"2022/22-506","sc":1,"by":{"1":"21","2":"15, 16"}},{"t":"case","label":"Bray v. The Atalanta","cite":"4 F. Cas. 37","y":1794,"court":"D.S.C.","url":"https://www.courtlistener.com/c/F.%20Cas./4/37/","by":{"1":"46"}},{"t":"case","label":"Caron v. United States","cite":"524 U.S. 308","y":1998,"id":"1997/97-6270","sc":1,"by":{"1":"48"}},{"t":"case","label":"City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"The canon against surplusage is strongest when an interpretation would render superfluous another part of the same statutory scheme,","cite":"141 S. Ct. 585, 591"}]},{"t":"case","label":"Commonwealth v. Martin","cite":"17 Mass. 359","y":1821,"url":"https://www.courtlistener.com/c/Mass./17/359/","by":{"1":"46"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"to ensure both that there is fair warning of the boundaries of criminal conduct and that legislatures, not courts, define criminal liability.","cite":"494 U.S. 152, 158"}]},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"by":{"1":"4"}},{"t":"case","label":"General Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"relents when a word used has several commonly understood meanings among which a speaker can alternate in the course of an ordinary conversation, without being confused or getting confusing,","cite":"540 U.S. 581, 595-596"}]},{"t":"case","label":"Graham County Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"by":{"1":"16"}},{"t":"case","label":"Hubbard v. United States","cite":"514 U.S. 695","y":1995,"id":"1994/94-172","sc":1,"by":{"1":"33"}},{"t":"case","label":"Lockhart v. United States","cite":"577 U.S. 347","y":2016,"id":"2015/14-8358","sc":1,"by":{"1":"16"}},{"t":"case","label":"Luna Perez v. Sturgis Pub. Schs.","cite":"143 S. Ct. 859","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/859/","sc":1,"by":{"1":"44"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"by":{"1":"20"}},{"t":"case","label":"Ohio Adjutant General’s Dep’t v. Federal Labor Relations Auth.","cite":"143 S. Ct. 1193","y":2023,"id":"2022/21-1454","sc":1,"by":{"1":"17"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"‘cardinal principle’ of interpretation that courts ‘must give effect, if possible, to every clause and word of a statute.’","cite":"139 S. Ct. 1881, 1890"}]},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"by":{"1":"47"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"by":{"1":"11, 19"},"q":[{"src":"brief","b":1,"text":"so that no part will be inoperative or superfluous, void or insignificant.","cite":"138 S. Ct. 816, 824"}]},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"by":{"1":"15"}},{"t":"case","label":"Shaw v. National Union Fire Ins. Co. of Pittsburgh","cite":"605 F.3d 1250","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/605/1250/","by":{"1":"15"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"by":{"1":"47"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"by":{"1":"23"}},{"t":"case","label":"United States v. Angelos","cite":"345 F. Supp. 2d 1227","y":2004,"court":"D. Utah","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/345/1227/","by":{"1":"44"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"47"},"q":[{"src":"brief","b":1,"text":"after considering text, structure, history, and purpose, there remains a grievous ambiguity or uncertainty in the statute, such that the Court must simply guess as to what Congress intended.","cite":"572 U.S. 157, 172-173"}]},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"by":{"1":"47"}},{"t":"case","label":"United States v. One 1973 Rolls Royce","cite":"43 F.3d 794","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/43/794/","by":{"1":"26"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"1":"43"}},{"t":"const","label":"Article III, Section 2, Clause 1","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects.","by":{"1":"40","2":"8"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"3"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1985","by":{"1":"5"}},{"t":"usc","label":"2 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/2/1602","subs":["(8)(B)"],"stext":{"head":"§1602. Definitions","paras":[[0,"As used in this chapter:"],[0,"(1) Agency"],[1,"The term \"agency\" has the meaning given that term in section 551(1) of title 5."],[0,"(2) Client"],[1,"The term \"client\" means any person or entity that employs or retains another person for financial or other compensation to conduct lobbying activities on behalf of that person or entity. A person or entity whose employees act as lobbyists on its own behalf is both a client and an employer of such employees. In the case of a coalition or association that employs or retains other persons to conduct lobbying activities, the client is the coalition or association and not its individual members."],[0,"(3) Covered executive branch official"],[1,"The term \"covered executive branch official\" means—"],[2,"(A) the President;"],[2,"(B) the Vice President;"],[2,"(C) any officer or employee, or any other individual functioning in the capacity of such an officer or employee, in the Executive Office of the President;"],[2,"(D) any officer or employee serving in a position in level I, II, III, IV, or V of the Executive Schedule, as designated by statute or Executive order;"],[2,"(E) any member of the uniformed services whose pay grade is at or above O–7 under section 201 of title 37; and"],[2,"(F) any officer or employee serving in a position of a confidential, policy-determining, policy-making, or policy-advocating character described in section 7511(b)(2)(B) of title 5."],[0,"(4) Covered legislative branch official"],[1,"The term \"covered legislative branch official\" means—"],[2,"(A) a Member of Congress;"],[2,"(B) an elected officer of either House of Congress;"],[2,"(C) any employee of, or any other individual functioning in the capacity of an employee of—"],[3,"(i) a Member of Congress;"],[3,"(ii) a committee of either House of Congress;"],[3,"(iii) the leadership staff of the House of Representatives or the leadership staff of the Senate;"],[3,"(iv) a joint committee of Congress; and"],[3,"(v) a working group or caucus organized to provide legislative services or other assistance to Members of Congress; and"],[2,"(D) any other legislative branch employee serving in a position described under section 13101(13) of title 5."],[0,"(5) Employee"],[1,"The term \"employee\" means any individual who is an officer, employee, partner, director, or proprietor of a person or entity, but does not include—"],[2,"(A) independent contractors; or"],[2,"(B) volunteers who receive no financial or other compensation from the person or entity for their services."],[0,"(6) Foreign entity"],[1,"The term \"foreign entity\" means a foreign principal (as defined in section 1(b) of the Foreign Agents Registration Act of 1938 (22 U.S.C. 611(b))."],[0,"(7) Lobbying activities"],[1,"The term \"lobbying activities\" means lobbying contacts and efforts in support of such contacts, including preparation and planning activities, research and other background work that is intended, at the time it is performed, for use in contacts, and coordination with the lobbying activities of others."],[0,"(8) Lobbying contact"],[0,"(A) Definition"],[2,"The term \"lobbying contact\" means any oral or written communication (including an electronic communication) to a covered executive branch official or a covered legislative branch official that is made on behalf of a client with regard to—"],[3,"(i) the formulation, modification, or adoption of Federal legislation (including legislative proposals);"],[3,"(ii) the formulation, modification, or adoption of a Federal rule, regulation, Executive order, or any other program, policy, or position of the United States Government;"],[3,"(iii) the administration or execution of a Federal program or policy (including the negotiation, award, or administration of a Federal contract, grant, loan, permit, or license); or"],[3,"(iv) the nomination or confirmation of a person for a position subject to confirmation by the Senate."],[0,"(B) Exceptions"],[2,"The term \"lobbying contact\" does not include a communication that is—"],[3,"(i) made by a public official acting in the public official's official capacity;"],[3,"(ii) made by a representative of a media organization if the purpose of the communication is gathering and disseminating news and information to the public;"],[3,"(iii) made in a speech, article, publication or other material that is distributed and made available to the public, or through radio, television, cable television, or other medium of mass communication;"],[3,"(iv) made on behalf of a government of a foreign country or a foreign political party and disclosed under the Foreign Agents Registration Act of 1938 (22 U.S.C. 611 et seq.);"],[3,"(v) a request for a meeting, a request for the status of an action, or any other similar administrative request, if the request does not include an attempt to influence a covered executive branch official or a covered legislative branch official;"],[3,"(vi) made in the course of participation in an advisory committee subject to chapter 10 of title 5;"],[3,"(vii) testimony given before a committee, subcommittee, or task force of the Congress, or submitted for inclusion in the public record of a hearing conducted by such committee, subcommittee, or task force;"],[3,"(viii) information provided in writing in response to an oral or written request by a covered executive branch official or a covered legislative branch official for specific information;"],[3,"(ix) required by subpoena, civil investigative demand, or otherwise compelled by statute, regulation, or other action of the Congress or an agency, including any communication compelled by a Federal contract, grant, loan, permit, or license;"],[3,"(x) made in response to a notice in the Federal Register, Commerce Business Daily, or other similar publication soliciting communications from the public and directed to the agency official specifically designated in the notice to receive such communications;"],[3,"(xi) not possible to report without disclosing information, the unauthorized disclosure of which is prohibited by law;"],[3,"(xii) made to an official in an agency with regard to—"],[4,"(I) a judicial proceeding or a criminal or civil law enforcement inquiry, investigation, or proceeding; or"],[4,"(II) a filing or proceeding that the Government is specifically required by statute or regulation to maintain or conduct on a confidential basis,"],[0,"if that agency is charged with responsibility for such proceeding, inquiry, investigation, or filing;"],[3,"(xiii) made in compliance with written agency procedures regarding an adjudication conducted by the agency under section 554 of title 5 or substantially similar provisions;"],[3,"(xiv) a written comment filed in the course of a public proceeding or any other communication that is made on the record in a public proceeding;"],[3,"(xv) a petition for agency action made in writing and required to be a matter of public record pursuant to established agency procedures;"],[3,"(xvi) made on behalf of an individual with regard to that individual's benefits, employment, or other personal matters involving only that individual, except that this clause does not apply to any communication with—"],[4,"(I) a covered executive branch official, or"],[4,"(II) a covered legislative branch official (other than the individual's elected Members of Congress or employees who work under such Members' direct supervision),"],[0,"with respect to the formulation, modification, or adoption of private legislation for the relief of that individual;"],[3,"(xvii) a disclosure by an individual that is protected under the amendments made by the Whistleblower Protection Act of 1989, under chapter 4 of title 5, or under another provision of law;"],[3,"(xviii) made by—"],[4,"(I) a church, its integrated auxiliary, or a convention or association of churches that is exempt from filing a Federal income tax return under paragraph 2(A)(i) of section 6033(a) of title 26, or"],[4,"(II) a religious order that is exempt from filing a Federal income tax return under paragraph (2)(A)(iii) of such section 6033(a); and"],[3,"(xix) between—"],[4,"(I) officials of a self-regulatory organization (as defined in section 3(a)(26) of the Securities Exchange Act [15 U.S.C. 78c(a)(26)]) that is registered with or established by the Securities and Exchange Commission as required by that Act [15 U.S.C. 78a et seq.] or a similar organization that is designated by or registered with the Commodities Future Trading Commission as provided under the Commodity Exchange Act [7 U.S.C. 1 et seq.]; and"],[4,"(II) the Securities and Exchange Commission or the Commodities Future Trading Commission, respectively;"],[0,"relating to the regulatory responsibilities of such organization under that Act."],[0,"(9) Lobbying firm"],[1,"The term \"lobbying firm\" means a person or entity that has 1 or more employees who are lobbyists on behalf of a client other than that person or entity. The term also includes a self-employed individual who is a lobbyist."],[0,"(10) Lobbyist"],[1,"The term \"lobbyist\" means any individual who is employed or retained by a client for financial or other compensation for services that include more than one lobbying contact, other than an individual whose lobbying activities constitute less than 20 percent of the time engaged in the services provided by such individual to that client over a 3-month period."],[0,"(11) Media organization"],[1,"The term \"media organization\" means a person or entity engaged in disseminating information to the general public through a newspaper, magazine, other publication, radio, television, cable television, or other medium of mass communication."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/1602?type=usc&year=mostrecent&link-type=html"},"by":{"1":"40","2":"20"}},{"t":"usc","label":"5 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/5/105","stext":{"head":"§105. Executive agency","paras":[[0,"For the purpose of this title, \"Executive agency\" means an Executive department, a Government corporation, and an independent establishment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/105?type=usc&year=mostrecent&link-type=html"},"by":{"1":"17, 41","2":"8"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"Section 105, \"executive agency\" means an executive department, a government corporation, and an independent establishment. Or sometimes examples are framed in the negative, such as 26 U.S.C."}]},{"t":"usc","label":"18 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/18/202","subs":["(d)"],"by":{"1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 212","url":"https://www.law.cornell.edu/uscode/text/18/212","subs":["(c)(2)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 229A","url":"https://www.law.cornell.edu/uscode/text/18/229A","subs":["(c)"],"by":{"1":"40, 41"}},{"t":"usc","label":"18 U.S.C. § 232","url":"https://www.law.cornell.edu/uscode/text/18/232","subs":["(5)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/18/341","by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/18/601","subs":["(b)(2)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)"],"by":{"1":"44"}},{"t":"usc","label":"18 U.S.C. § 925","url":"https://www.law.cornell.edu/uscode/text/18/925","subs":["(a)(2)"],"by":{"1":"40","2":"20"}},{"t":"usc","label":"18 U.S.C. § 926B","url":"https://www.law.cornell.edu/uscode/text/18/926B","subs":["(e)(3)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 1963","url":"https://www.law.cornell.edu/uscode/text/18/1963","subs":["(h)"],"by":{"1":"40, 41","2":"8, 20"}},{"t":"usc","label":"18 U.S.C. § 2510","url":"https://www.law.cornell.edu/uscode/text/18/2510","subs":["(9)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 3486","url":"https://www.law.cornell.edu/uscode/text/18/3486","subs":["(a)(1)(B)"],"by":{"1":"40, 41"}},{"t":"usc","label":"18 U.S.C. § 4130","url":"https://www.law.cornell.edu/uscode/text/18/4130","subs":["(a)"],"by":{"1":"41"}},{"t":"usc","label":"21 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/21/802","subs":["(57)"],"by":{"1":"7, 22"}},{"t":"usc","label":"21 U.S.C. § 851","url":"https://www.law.cornell.edu/uscode/text/21/851","by":{"1":"7"}},{"t":"usc","label":"26 U.S.C. § 104","url":"https://www.law.cornell.edu/uscode/text/26/104","subs":["(a)"],"by":{"1":"41"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","subs":["(f)(16)(D)"],"stext":{"head":"§170. Charitable, etc., contributions and gifts","paras":[[0,"(a) Allowance of deduction"],[0,"(1) General rule"],[1,"There shall be allowed as a deduction any charitable contribution (as defined in subsection (c)) payment of which is made within the taxable year. A charitable contribution shall be allowable as a deduction only if verified under regulations prescribed by the Secretary."],[0,"(2) Corporations on accrual basis"],[1,"In the case of a corporation reporting its taxable income on the accrual basis, if—"],[2,"(A) the board of directors authorizes a charitable contribution during any taxable year, and"],[2,"(B) payment of such contribution is made after the close of such taxable year and on or before the 15th day of the fourth month following the close of such taxable year,"],[1,"then the taxpayer may elect to treat such contribution as paid during such taxable year. The election may be made only at the time of the filing of the return for such taxable year, and shall be signified in such manner as the Secretary shall by regulations prescribe."],[0,"(3) Future interests in tangible personal property"],[1,"For purposes of this section, payment of a charitable contribution which consists of a future interest in tangible personal property shall be treated as made only when all intervening interests in, and rights to the actual possession or enjoyment of, the property have expired or are held by persons other than the taxpayer or those standing in a relationship to the taxpayer described in section 267(b) or 707(b). For purposes of the preceding sentence, a fixture which is intended to be severed from the real property shall be treated as tangible personal property."],[0,"(b) Percentage limitations"],[0,"(1) Individuals"],[1,"In the case of an individual, the deduction provided in subsection (a) shall be limited as provided in the succeeding subparagraphs."],[0,"(A) General rule"],[2,"Any charitable contribution to—"],[3,"(i) a church or a convention or association of churches,"],[3,"(ii) an educational organization which normally maintains a regular faculty and curriculum and normally has a regularly enrolled body of pupils or students in attendance at the place where its educational activities are regularly carried on,"],[3,"(iii) an organization the principal purpose or functions of which are the providing of medical or hospital care or medical education or medical research, if the organization is a hospital, or if the organization is a medical research organization directly engaged in the continuous active conduct of medical research in conjunction with a hospital, and during the calendar year in which the contribution is made such organization is committed to spend such contributions for such research before January 1 of the fifth calendar year which begins after the date such contribution is made,"],[3,"(iv) an organization which normally receives a substantial part of its support (exclusive of income received in the exercise or performance by such organization of its charitable, educational, or other purpose or function constituting the basis for its exemption under section 501(a)) from the United States or any State or political subdivision thereof or from direct or indirect contributions from the general public, and which is organized and operated exclusively to receive, hold, invest, and administer property and to make expenditures to or for the benefit of a college or university which is an organization referred to in clause (ii) of this subparagraph and which is an agency or instrumentality of a State or political subdivision thereof, or which is owned or operated by a State or political subdivision thereof or by an agency or instrumentality of one or more States or political subdivisions,"],[3,"(v) a governmental unit referred to in subsection (c)(1),"],[3,"(vi) an organization referred to in subsection (c)(2) which normally receives a substantial part of its support (exclusive of income received in the exercise or performance by such organization of its charitable, educational, or other purpose or function constituting the basis for its exemption under section 501(a)) from a governmental unit referred to in subsection (c)(1) or from direct or indirect contributions from the general public,"],[3,"(vii) a private foundation described in subparagraph (F),"],[3,"(viii) an organization described in section 509(a)(2) or (3),"],[3,"(ix) an agricultural research organization directly engaged in the continuous active conduct of agricultural research (as defined in section 1404 of the National Agricultural Research, Extension, and Teaching Policy Act of 1977) in conjunction with a land-grant college or university (as defined in such section) or a non-land grant college of agriculture (as defined in such section), and during the calendar year in which the contribution is made such organization is committed to spend such contribution for such research before January 1 of the fifth calendar year which begins after the date such contribution is made, or"],[3,"(x) an organization described in section 501(c)(19) that is a federally chartered corporation,"],[2,"shall be allowed to the extent that the aggregate of such contributions does not exceed 50 percent of the taxpayer's contribution base for the taxable year."],[0,"(B) Other contributions"],[2,"Any charitable contribution other than a charitable contribution to which subparagraph (A) applies shall be allowed to the extent that the aggregate of such contributions does not exceed the lesser of—"],[3,"(i) 30 percent of the taxpayer's contribution base for the taxable year, or"],[3,"(ii) the excess of 50 percent of the taxpayer's contribution base for the taxable year over the amount of charitable contributions allowable under subparagraph (A) (determined without regard to subparagraph (C))."],[2,"If the aggregate of such contributions exceeds the limitation of the preceding sentence, such excess shall be treated (in a manner consistent with the rules of subsection (d)(1)) as a charitable contribution (to which subparagraph (A) does not apply) in each of the 5 succeeding taxable years in order of time."],[0,"(C) Special limitation with respect to contributions described in subparagraph (A) of certain capital gain property"],[3,"(i) In the case of charitable contributions described in subparagraph (A) of capital gain property to which subsection (e)(1)(B) does not apply, the total amount of contributions of such property which may be taken into account under subsection (a) for any taxable year shall not exceed 30 percent of the taxpayer's contribution base for such year. For purposes of this subsection, contributions of capital gain property to which this subparagraph applies shall be taken into account after all other charitable contributions (other than charitable contributions to which subparagraph (D) applies)."],[3,"(ii) If charitable contributions described in subparagraph (A) of capital gain property to which clause (i) applies exceeds 30 percent of the taxpayer's contribution base for any taxable year, such excess shall be treated, in a manner consistent with the rules of subsection (d)(1), as a charitable contribution of capital gain property to which clause (i) applies in each of the 5 succeeding taxable years in order of time."],[3,"(iii) At the election of the taxpayer (made at such time and in such manner as the Secretary prescribes by regulations), subsection (e)(1) shall apply to all contributions of capital gain property (to which subsection (e)(1)(B) does not otherwise apply) made by the taxpayer during the taxable year. If such an election is made, clauses (i) and (ii) shall not apply to contributions of capital gain property made during the taxable year, and, in applying subsection (d)(1) for such taxable year with respect to contributions of capital gain property made in any prior contribution year for which an election was not made under this clause, such contributions shall be reduced as if subsection (e)(1) had applied to such contributions in the year in which made."],[3,"(iv) For purposes of this paragraph, the term \"capital gain property\" means, with respect to any contribution, any capital asset the sale of which at its fair market value at the time of the contribution would have resulted in gain which would have been long-term capital gain. For purposes of the preceding sentence, any property which is property used in the trade or business (as defined in section 1231(b)) shall be treated as a capital asset."],[0,"(D) Special limitation with respect to contributions of capital gain property to organizations not described in subparagraph (A)"],[0,"(i) In general"],[3,"In the case of charitable contributions (other than charitable contributions to which subparagraph (A) applies) of capital gain property, the total amount of such contributions of such property taken into account under subsection (a) for any taxable year shall not exceed the lesser of—"],[4,"(I) 20 percent of the taxpayer's contribution base for the taxable year, or"],[4,"(II) the excess of 30 percent of the taxpayer's contribution base for the taxable year over the amount of the contributions of capital gain property to which subparagraph (C) applies."],[0,"For purposes of this subsection, contributions of capital gain property to which this subparagraph applies shall be taken into account after all other charitable contributions."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/170?type=usc&year=mostrecent&link-type=html"},"by":{"1":"40, 41","2":"8"},"q":[{"src":"brief","b":1,"text":"does not include—(I) food, (II) paintings, antiques, and other objects of art, (III), jewelry and gems, and (IV) collections.","cite":"26 U.S.C. 170"}]},{"t":"usc","label":"26 U.S.C. § 871","url":"https://www.law.cornell.edu/uscode/text/26/871","subs":["(h)(4)(C)"],"by":{"1":"41"}},{"t":"usc","label":"31 U.S.C. § 9701","url":"https://www.law.cornell.edu/uscode/text/31/9701","subs":["(c)"],"by":{"1":"41"}},{"t":"usc","label":"33 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/33/2241","subs":["(4)","(5)"],"by":{"1":"41, 41"}},{"t":"usc","label":"34 U.S.C. § 20101","url":"https://www.law.cornell.edu/uscode/text/34/20101","subs":["(b)(1)","(f)"],"by":{"1":"17, 17, 38","2":"8, 11"}},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(b)"],"by":{"1":"41"}},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","subs":["(a)(2)"],"by":{"1":"41"}},{"t":"usc","label":"46 U.S.C. § 8103","url":"https://www.law.cornell.edu/uscode/text/46/8103","subs":["(b)(2)"],"by":{"1":"41"}},{"t":"usc","label":"49 U.S.C. § 28301","url":"https://www.law.cornell.edu/uscode/text/49/28301","subs":["(b)(1)"],"by":{"1":"41"}},{"t":"usc","label":"52 U.S.C. § 30118","url":"https://www.law.cornell.edu/uscode/text/52/30118","subs":["(b)(2)"],"by":{"1":"41"}},{"t":"reg","label":"88 Fed. Reg. 7186","url":"https://www.govinfo.gov/link/fr/88/7186","by":{"1":"45"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"143 S. Ct. 665","y":2023,"id":"2022/21-908","sc":1,"by":{"2":"10"},"q":[{"src":"brief","b":2,"text":"to rewrite this statute (or any other).","cite":"143 S. Ct. 665, 675"}]},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"2":"16"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"from giving the text its ordinary meaning.","cite":"141 S. Ct. 1532, 1542"}]},{"t":"case","label":"Mills Music, Inc. v. Snyder","cite":"469 U.S. 153","y":1985,"id":"1984/83-1153","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"assume that the ordinary meaning of the language that Congress employed ‘accurately expresses the legislative purpose.’","cite":"469 U.S. 153, 164"}]},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"by":{"2":"6"},"q":[{"src":"brief","b":2,"text":"it easily could have drafted language to that effect.","cite":"571 U.S. 161, 169"}]},{"t":"case","label":"Mount Lemmon Fire District v. Guido","cite":"139 S. Ct. 22","y":2018,"id":"2018/17-587","sc":1,"by":{"2":"7"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"by":{"2":"7"}},{"t":"case","label":"Slack Technologies, LLC v. Pirani","cite":"143 S. Ct. 1433","y":2023,"id":"2022/22-200","sc":1,"by":{"2":"20, 21"}},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"by":{"2":"4, 23"}},{"t":"case","label":"United States v. Owens","cite":"38 F.4th 1","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/1/","by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"safety valve eligibility does not guarantee [a defendant] a below-statutory minimum sentence.","cite":"38 F.4th 1, 3"}]},{"t":"case","label":"United States v. Quirante","cite":"486 F.3d 1273","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/486/1273/","by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"[A] court compelled to disregard a mandatory minimum sentence … may vary upward to and even past the mandatory minimum,","cite":"486 F.3d 1273, 1276"}]},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"2":"8"}},{"t":"const","label":"Article I, Section 8, Clause 10","text":"To define and punish Piracies and Felonies committed on the high Seas, and Offences against the Law of Nations;","by":{"2":"8"}},{"t":"const","label":"Article I, Section 8, Clause 11","clauses":[["war-powers","War Powers Clause"]],"text":"To declare War, grant Letters of Marque and Reprisal, and make Rules concerning Captures on Land and Water;","by":{"2":"8, 11"}}]};